import{_ as n,a0 as s,w as l,s as a,I as f,x as i,a1 as p,A as o,ao as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"LibreOffice 和 OpenOffice 的相似与不同之处 | LCTT x X-CMD","titleTemplate":false,"description":"LibreOffice 和 OpenOffice 的相似与不同之处 | LCTT (202308) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LibreOffice 和 OpenOffice 的相似与不同之处 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LibreOffice 和 OpenOffice 的相似与不同之处 | LCTT (202308) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202308/20220728 LibreOffice vs OpenOffice- All You Need to Know-","title":"LibreOffice 和 OpenOffice 的相似与不同之处","tag":"202308","desc":""},"relativePath":"202308/20220728 LibreOffice vs OpenOffice- All You Need to Know-.md","filePath":"[post].md"}'),O={name:"202308/20220728 LibreOffice vs OpenOffice- All You Need to Know-.md"};function b(m,e,d,u,c,L){const r=s("Link");return l(),a("div",null,[e[39]||(e[39]=f("h1",{id:"libreoffice-和-openoffice-的相似与不同之处",tabindex:"-1"},[i("LibreOffice 和 OpenOffice 的相似与不同之处 "),f("a",{class:"header-anchor",href:"#libreoffice-和-openoffice-的相似与不同之处","aria-label":"Permalink to “LibreOffice 和 OpenOffice 的相似与不同之处”"},"​")],-1)),e[40]||(e[40]=f("p",null,[f("img",{src:"https://img.linux.net.cn/data/attachment/album/202308/10/143846kry5mmrmlll3bgql.jpg",alt:""})],-1)),e[41]||(e[41]=f("blockquote",null,[f("p",null,"对两个最受欢迎的开源办公软件的比较。了解 LibreOffice 和 OpenOffice 之间的相似与不同之处。")],-1)),f("p",null,[e[1]||(e[1]=i("LibreOffice 与 OpenOffice 是两个流行的微软办公套件的 ",-1)),p(r,{href:"https://itsfoss.com/best-free-open-source-alternatives-microsoft-office/"},{default:o(()=>[...e[0]||(e[0]=[i("开源替代品",-1)])]),_:1}),e[2]||(e[2]=i("。",-1))]),e[42]||(e[42]=t('<p>如果你正在寻找一个具备文字处理、电子表格、演示和其他几个程序的开源办公套件，那么这两个办公软件都可以推荐。</p><p>然而，要充分利用这些办公套件，你应该了解它们之间的差异，以决定哪个最适合你。</p><p>你应该使用 LibreOffice 还是 OpenOffice？它们之间有什么区别？在这里，我将更详细地探讨这些问题。</p><h3 id="libreoffice-vs-openoffice-起源" tabindex="-1">LibreOffice vs. OpenOffice：起源 <a class="header-anchor" href="#libreoffice-vs-openoffice-起源" aria-label="Permalink to “LibreOffice vs. OpenOffice：起源”">​</a></h3><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/libreoffice-vs-openoffice.jpg" alt=""></p><p>OpenOffice 是由 <ruby>昇阳微系统<rt>Sun Microsystems</rt></ruby> 开发的项目。它是（他们最初收购的）与微软办公套件竞争的 StarOffice 的开源版本。</p><p>后来，<ruby>甲骨文<rt>Oracle</rt></ruby> 收购了昇阳微系统，并最终放弃了 OpenOffice.org（OOo），将代码库交给了 Apache。</p><p>在 Apache 开始维护它时，该办公套件的名称被更改为 “OpenOffice” 或 “Apache OpenOffice”。</p><p>在这个过渡期间，出于担心 Oracle 会停止该项目，<ruby>文档基金会<rt>The Document Foundation</rt></ruby> 复刻了 OpenOffice.org，创建了 LibreOffice。</p><p>因此，LibreOffice 是作为 OpenOffice.org 的替代品而创建的。</p><p>但是，现在 OpenOffice 仍然存在并得到积极维护（LCTT 译注：不是），为什么你应该选择 LibreOffice？OpenOffice 不够好吗？它们之间有什么相似之处？</p><h3 id="libreoffice-和-apache-openoffice-有什么共同之处" tabindex="-1">LibreOffice 和 Apache OpenOffice 有什么共同之处？ <a class="header-anchor" href="#libreoffice-和-apache-openoffice-有什么共同之处" aria-label="Permalink to “LibreOffice 和 Apache OpenOffice 有什么共同之处？”">​</a></h3><p>LibreOffice 和 Apache OpenOffice 有一些共同之处：</p><p>如果你只需要创建基本文档、电子表格或演示文稿，并不需要进行任何复杂操作或快捷方式来提高生产力，那么你可以使用它们中的任何一个。</p><p>简单来说，如果你在 Linux、Windows 和 macOS 上需要一个开源办公套件，这两个软件都可以胜任。</p><p>LibreOffice 和 Apache OpenOffice 都能够打开包括微软的 DOCX、PPT 等在内的各种文件格式。</p><p>但是，当你需要<strong>不同的功能、用户界面、文件格式兼容性、导出能力</strong>和其他特性时，它们之间的相似之处就会逐渐消失。</p><p>当然，如果你开始广泛使用它们，你将会注意到它们之间的差异。</p><p>为了节省你的麻烦，让我在这里重点指出这些差异：</p><h3 id="安装和平台可用性" tabindex="-1">安装和平台可用性 <a class="header-anchor" href="#安装和平台可用性" aria-label="Permalink to “安装和平台可用性”">​</a></h3><p>用户体验的第一步是安装过程和平台可用性。</p><p>如果安装复杂且不支持多个平台，那么这个程序就令人失望。</p><p>在这种情况下，LibreOffice 和 Apache OpenOffice 官方支持 <strong>Linux、Windows 和 macOS</strong>。</p>',23)),f("p",null,[e[4]||(e[4]=i("至于移动平台，你可以在谷歌 Play 商店（安卓）和苹果应用商店（iOS）上找到基于 LibreOffice 的 ",-1)),p(r,{href:"https://www.collaboraoffice.com/"},{default:o(()=>[...e[3]||(e[3]=[i("Collabora Office",-1)])]),_:1}),e[5]||(e[5]=i("。考虑到 Collabora 是 LibreOffice 的商业合作伙伴，它几乎可以视为 LibreOffice 的官方移植版。",-1))]),e[43]||(e[43]=f("p",null,[i("而对于移动设备上的 OpenOffice，虽然你也可以使用其他社区/第三方移植版替代，"),f("strong",null,"但它没有官方移植版可用"),i("。")],-1)),e[44]||(e[44]=f("p",null,"现在你已经了解了支持的平台，它们的安装是否容易？",-1)),e[45]||(e[45]=f("p",null,[f("strong",null,"对于 Linux"),i("，LibreOffice 在官方软件库中可用，并在软件中心和软件包管理器中列出。因此，你只需点击几下即可在 Linux 系统上安装它。")],-1)),e[46]||(e[46]=f("p",null,[f("img",{src:"https://itsfoss.com/content/images/wordpress/2022/07/libreoffice-software-center.png",alt:"libreoffice software center"})],-1)),e[47]||(e[47]=f("p",null,"不幸的是，OpenOffice 的安装过程比较麻烦。它不在软件库中，软件中心中也找不到它。而且，如果你已经预先安装了 LibreOffice，则在尝试安装 OpenOffice 之前必须先删除任何痕迹（以避免安装冲突）。",-1)),f("p",null,[e[7]||(e[7]=i("你需要从其网站下载官方软件包（根据你的 Linux 发行版），然后解压缩，并使用一些命令来",-1)),p(r,{href:"https://itsfoss.com/install-openoffice-ubuntu-linux/"},{default:o(()=>[...e[6]||(e[6]=[i("在 Linux 上安装 OpenOffice",-1)])]),_:1}),e[8]||(e[8]=i("。",-1))]),e[48]||(e[48]=f("p",null,[f("img",{src:"https://itsfoss.com/content/images/wordpress/2022/07/openoffice-debs-linux.png",alt:"openoffice debs linux"})],-1)),f("p",null,[e[10]||(e[10]=f("strong",null,"对于 Windows 和 macOS",-1)),e[11]||(e[11]=i("，安装非常简单，你只需 ",-1)),p(r,{href:"https://www.libreoffice.org/download/download/"},{default:o(()=>[...e[9]||(e[9]=[i("下载安装包",-1)])]),_:1}),e[12]||(e[12]=i("，然后按照屏幕上的指示进行操作即可。",-1))]),f("p",null,[p(r,{href:"https://www.libreoffice.org/download/libreoffice-from-microsoft-and-mac-app-stores/"},{default:o(()=>[...e[13]||(e[13]=[i("LibreOffice 还提供了另一种方式",-1)])]),_:1}),e[14]||(e[14]=i(" 可供获取（通过合作伙伴），即通过微软商店和 Mac 应用商店。不过，你需要支付费用。其中的一部分将捐赠给文档基金会，一部分用于 LibreOffice 的开发。",-1))]),f("p",null,[e[16]||(e[16]=i("还要注意，由于 ",-1)),p(r,{href:"https://www.collaboraoffice.com/press-releases/collabora-office-ships-for-chromebooks/"},{default:o(()=>[...e[15]||(e[15]=[i("Collabora Office",-1)])]),_:1}),e[17]||(e[17]=i("，你也可以在 Chromebook 上使用 LibreOffice。",-1))]),e[49]||(e[49]=t('<p><strong>总而言之，LibreOffice 提供了更好的平台可用性和更轻松的安装过程，这使得 OpenOffice 成为一个不太推荐的选择。</strong></p><h3 id="用户体验" tabindex="-1">用户体验 <a class="header-anchor" href="#用户体验" aria-label="Permalink to “用户体验”">​</a></h3><p>LibreOffice 提供了一个令人愉悦的用户界面，与现代标准相融合。LibreOffice 在大多数现代硬件上看起来都很好，不论你使用的是 2K 显示器还是 4K 显示器。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/libreoffice-home-1.png" alt="libreoffice home 1"></p><p>你可以从主启动器快速访问所有工具，这是一种良好的体验。Writer、Calc 和其他程序提供了一个易于使用且看起来井然有序的界面。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/libreoffice-writer.png" alt="libreoffice writer"></p><p>Apache OpenOffice 提供的是一个过时的用户界面。因此，如果你正在寻找一个现代化的开源办公套件，LibreOffice 是首选。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/openoffice-home.png" alt="openoffice home"></p><p>当然，一些用户喜欢经典的用户界面，因为他们对此很熟悉，并且在旧硬件上的使用受到限制。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/openoffice-writer.png" alt="openoffice writer"></p><p>换句话说，OpenOffice 仍然可用，但对于大多数现代用户来说可能不是一种直观的体验。</p><p>如果你仔细比较用户界面元素，这将取决于你阅读本文时可用的最新版本。因此，我们避免进行具体的视觉比较。</p><h3 id="特点" tabindex="-1">特点 <a class="header-anchor" href="#特点" aria-label="Permalink to “特点”">​</a></h3><p>强大的功能集的需求取决于你处理的文件类型。</p><p>默认情况下，OpenOffice 和 LibreOffice 均提供以下程序：</p><ul><li>Math（科学公式）</li><li>Writer（文档）</li><li>Impress（演示文稿）</li><li>Draw（绘图、流程图等）</li><li>Calc（电子表格）</li><li>Base（数据库）</li></ul><p>无论你使用文字处理器（Writer）、电子表格（Calc）还是演示文稿（Impress），你都可以获得相同的标准功能。</p><p>然而，如果你处理需要访问<strong>更多模板、函数、导入/导出选项和高级格式设置</strong>的复杂文档，LibreOffice 会更优秀一些。</p><h3 id="文件格式兼容性" tabindex="-1">文件格式兼容性 <a class="header-anchor" href="#文件格式兼容性" aria-label="Permalink to “文件格式兼容性”">​</a></h3><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/file-format-illustration.jpg" alt=""></p><p>OpenOffice 支持几乎与 LibreOffice 相同的文件扩展名。</p><p>但是，LibreOffice 还支持一些 OpenOffice 不支持的文件格式导出。</p><p>例如，你可以在 OpenOffice 中打开 <strong>.DOCX</strong> 文件，但无法保留文件扩展名保存/导出该文件。</p><p>你只能将其保存为 .odt/.doc./.ott 等几种类似的文件格式。</p><p>同样，你无法得到对 .xslx 和 .pptx 的支持，这些是通常用于电子表格和演示文稿的现代文件格式。</p><p>当然，如果你不依赖于这些文件格式，可以尝试使用 OpenOffice。然而，与使用较新文件格式的用户进行协作时，你将遇到可能影响你工作的兼容性/格式设置问题。</p><p>考虑到 OpenOffice 缺乏许多功能，依赖它来访问较新的文件格式可能不明智；由于不良的兼容性，你可能会丢失重要的细节。</p><h3 id="更新" tabindex="-1">更新 <a class="header-anchor" href="#更新" aria-label="Permalink to “更新”">​</a></h3><p><img src="https://itsfoss.com/content/images/wordpress/2022/07/software-update-illustration.jpg" alt=""></p><p>为了提高你使用该程序的效率并获得增强的性能、新功能和安全修复，建议选择定期获得更新的软件工具。</p><p>从技术上讲，两者都会定期获得更新。但是，OpenOffice 仅限于修复错误和进行小型更新。</p><p>LibreOffice 的开发活动更加活跃，频繁修复错误/进行小型更新，定期进行较大的升级，增加新功能和改善用户体验。</p>',32)),f("p",null,[e[19]||(e[19]=i("难怪 ",-1)),p(r,{href:"https://itsfoss.com/libreoffice-letter-openoffice/"},{default:o(()=>[...e[18]||(e[18]=[i("LibreOffice 给 Apache 写了一封公开信",-1)])]),_:1}),e[20]||(e[20]=i("，请求停止开发 OpenOffice 并将这些资源转用于帮助 LibreOffice 的开发。",-1))]),e[50]||(e[50]=f("h3",{id:"企业支持和在线协作选项",tabindex:"-1"},[i("企业支持和在线协作选项 "),f("a",{class:"header-anchor",href:"#企业支持和在线协作选项","aria-label":"Permalink to “企业支持和在线协作选项”"},"​")],-1)),e[51]||(e[51]=f("p",null,[f("img",{src:"https://itsfoss.com/content/images/wordpress/2022/07/enterprise-illustration.jpg",alt:""})],-1)),f("p",null,[e[23]||(e[23]=i("有了 ",-1)),p(r,{href:"https://www.collaboraoffice.com/"},{default:o(()=>[...e[21]||(e[21]=[i("Collabora Office",-1)])]),_:1}),e[24]||(e[24]=i("，你可以获得企业支持，并能够在工作场所使用 LibreOffice。通过 ",-1)),p(r,{href:"https://www.collaboraoffice.com/collabora-online/"},{default:o(()=>[...e[22]||(e[22]=[i("Collabora Online",-1)])]),_:1}),e[25]||(e[25]=i("，你还可以在服务器上部署 LibreOffice 以实现协作工作空间。",-1))]),e[52]||(e[52]=t('<p>遗憾的是，Apache OpenOffice 没有任何企业支持选项。因此，如果有的话，它最适合家庭用户使用。</p><h3 id="许可" tabindex="-1">许可 <a class="header-anchor" href="#许可" aria-label="Permalink to “许可”">​</a></h3><p>对于使用这些程序并无任何许可问题，也不会阻止或使你不愿使用它们。然而，这些信息对于项目的贡献者可能会有所帮助。</p><p>LibreOffice 使用 Mozilla Public License v2.0 许可证，而 Apache OpenOffice 则使用 Apache License 2.0 许可证。</p><h3 id="libreoffice-vs-openoffice-应该选择哪个" tabindex="-1">LibreOffice vs. OpenOffice：应该选择哪个？ <a class="header-anchor" href="#libreoffice-vs-openoffice-应该选择哪个" aria-label="Permalink to “LibreOffice vs. OpenOffice：应该选择哪个？”">​</a></h3><p>基于现代设计、更多功能和对较新文件格式的支持，LibreOffice 是一个易于推荐的选择。</p><p>OpenOffice 可以是适用于熟悉旧版办公套件界面，且希望在 32 位系统中无障碍运行的用户的解决方案。在 LibreOffice 由于某些原因无法正常工作的情况下，OpenOffice 应该作为备选方案。</p><p>我们可以告诉你选择取决于个人喜好，但如果你经常处理文档，如果我不说 LibreOffice 是更好的选择，那么我显然不够诚恳。</p><p><em>（题图：MJ/52f9aa1b-3529-492a-a5fb-7b24b62e2e8a）</em></p><hr>',10)),f("p",null,[e[27]||(e[27]=i("via: ",-1)),p(r,{href:"https://itsfoss.com/libreoffice-vs-openoffice/"},{default:o(()=>[...e[26]||(e[26]=[i("https://itsfoss.com/libreoffice-vs-openoffice/",-1)])]),_:1})]),f("p",null,[e[31]||(e[31]=i("作者：",-1)),p(r,{href:"https://itsfoss.com/author/ankush/"},{default:o(()=>[...e[28]||(e[28]=[i("Ankush Das",-1)])]),_:1}),e[32]||(e[32]=i(" 选题：",-1)),p(r,{href:"https://github.com/lkxed"},{default:o(()=>[...e[29]||(e[29]=[i("lkxed",-1)])]),_:1}),e[33]||(e[33]=i(" 译者：ChatGPT 校对：",-1)),p(r,{href:"https://github.com/wxy"},{default:o(()=>[...e[30]||(e[30]=[i("wxy",-1)])]),_:1})]),f("p",null,[e[36]||(e[36]=i("本文由 ",-1)),p(r,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[34]||(e[34]=[i("LCTT",-1)])]),_:1}),e[37]||(e[37]=i(" 原创编译，",-1)),p(r,{href:"https://linux.cn/"},{default:o(()=>[...e[35]||(e[35]=[i("Linux中国",-1)])]),_:1}),e[38]||(e[38]=i(" 荣誉推出",-1))])])}const x=n(O,[["render",b]]);export{T as __pageData,x as default};
